-- Real storefront snapshot, imported without deleting legacy products or changing stock.
-- Logical image keys are resolved by frontend/src/assets/productImages.js.
CREATE TABLE storefront_products (
  product_id UUID PRIMARY KEY REFERENCES products(id),
  catalog_key VARCHAR(150) NOT NULL UNIQUE,
  original_price NUMERIC(15,2) NOT NULL CHECK (original_price >= 0),
  specs JSONB NOT NULL DEFAULT '[]'::jsonb,
  provenance JSONB NOT NULL,
  sort_order INTEGER NOT NULL
);
CREATE TABLE storefront_articles (
  slug VARCHAR(255) PRIMARY KEY,
  content JSONB NOT NULL,
  published BOOLEAN NOT NULL DEFAULT TRUE,
  sort_order INTEGER NOT NULL
);
ALTER TABLE storefront_products ENABLE ROW LEVEL SECURITY;
ALTER TABLE storefront_articles ENABLE ROW LEVEL SECURITY;

